import redis
s_errors=[]; counts={}
for db in range(16):
 a=redis.Redis(port=6379,db=db); b=redis.Redis(port=6380,db=db)
 ka=set(a.scan_iter()); kb=set(b.scan_iter()); counts[db]=(len(ka),len(kb))
 if ka!=kb:s_errors.append((db,'key sets',len(ka-kb),len(kb-ka)))
 for k in ka&kb:
  t=a.type(k)
  if t!=b.type(k): s_errors.append((db,k,'type'));continue
  at=a.pexpiretime(k);bt=b.pexpiretime(k)
  if at!=bt:s_errors.append((db,k,'expiretime',at,bt))
  if t==b'string':eq=a.get(k)==b.get(k)
  elif t==b'hash':eq=a.hgetall(k)==b.hgetall(k)
  elif t==b'list':eq=a.lrange(k,0,-1)==b.lrange(k,0,-1)
  elif t==b'set':eq=a.smembers(k)==b.smembers(k)
  elif t==b'zset':eq=a.zrange(k,0,-1,withscores=True)==b.zrange(k,0,-1,withscores=True)
  elif t==b'stream':
   eq=a.xrange(k)==b.xrange(k) and a.xinfo_stream(k)==b.xinfo_stream(k)
   ag=a.xinfo_groups(k);bg=b.xinfo_groups(k)
   eq=eq and ag==bg
   for g in ag:
    n=g['name']; ac=a.xinfo_consumers(k,n);bc=b.xinfo_consumers(k,n)
    # idle/inactive values can drift between sequential calls
    eq=eq and [(x['name'],x['pending']) for x in ac]==[(x['name'],x['pending']) for x in bc]
    ap=a.xpending_range(k,n,'-','+',100000);bp=b.xpending_range(k,n,'-','+',100000)
    eq=eq and [(x['message_id'],x['consumer'],x['times_delivered']) for x in ap]==[(x['message_id'],x['consumer'],x['times_delivered']) for x in bp]
  else: eq=False
  if not eq:s_errors.append((db,k,'value/group mismatch'))
print('DB counts:',counts)
print('errors:',len(s_errors),s_errors[:20])
if s_errors:raise SystemExit(1)
